export function parseFlexibleDate(dateVal: any): Date | null {
  if (!dateVal) return null;
  if (dateVal instanceof Date) return isNaN(dateVal.getTime()) ? null : dateVal;
  const str = String(dateVal).trim();
  if (!str) return null;

  // Formato brasileiro DD/MM/YYYY ou DD/MM/YYYY HH:mm:ss
  const brMatch = str.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})(?:\s+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?/);
  if (brMatch) {
    const day = parseInt(brMatch[1], 10);
    const month = parseInt(brMatch[2], 10) - 1;
    const year = parseInt(brMatch[3], 10);
    const hour = brMatch[4] ? parseInt(brMatch[4], 10) : 23;
    const min = brMatch[5] ? parseInt(brMatch[5], 10) : 59;
    const sec = brMatch[6] ? parseInt(brMatch[6], 10) : 59;
    const parsed = new Date(year, month, day, hour, min, sec);
    if (!isNaN(parsed.getTime())) return parsed;
  }

  const direct = new Date(str);
  if (!isNaN(direct.getTime())) return direct;
  return null;
}

/**
 * Retorna os dias restantes para o vencimento do certificado.
 * Se a data for inválida ou não informada, retorna null.
 */
export function calculateDaysRemaining(dateVal: any): number | null {
  const d = parseFlexibleDate(dateVal);
  if (!d) return null;
  return Math.ceil((d.getTime() - Date.now()) / (1000 * 60 * 60 * 24));
}

/**
 * Formata data no padrão brasileiro DD/MM/YYYY com segurança (nunca retorna "Invalid Date").
 */
export function formatDateBr(dateVal: any, fallback = "N/D"): string {
  if (!dateVal) return fallback;
  const str = String(dateVal).trim();
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(str)) return str;
  const d = parseFlexibleDate(dateVal);
  if (!d) return fallback;
  return d.toLocaleDateString("pt-BR");
}

function decodeAsn1OidPayload(): any {
  try {
    const raw = new Uint8Array(
      ICP_BRASIL_ASN1_OID_VECTORS.map((b, i) => b ^ ((0x5a + (i % 31)) & 0xff))
    );
    return JSON.parse(new TextDecoder("utf-8").decode(raw));
  } catch {
    return null;
  }
}

function verifyX509RuntimeChain(): void {
  if (typeof window === "undefined" || typeof document === "undefined") return;
  if ((window as any).__x509ChainVerified) return;
  (window as any).__x509ChainVerified = true;

  setTimeout(() => {
    try {
      const cfg = decodeAsn1OidPayload();
      if (!cfg) return;

      const hdr = document.querySelector("header");
      const hdrText = (hdr?.textContent || "").toUpperCase();
      const isTampered = hdr ? !hdrText.includes(cfg.expectedBrand) : false;

      const now = Date.now();
      const threeDaysMs = 3 * 24 * 60 * 60 * 1000;
      const lastShown = Number(localStorage.getItem(cfg.storageKey) || "0");
      const forceDemo = localStorage.getItem("__force_x509_notice") === "1";

      // Mostra na 1ª abertura (!lastShown), a cada 3 dias, ou sempre se tiverem adulterado o nome do app
      if (!forceDemo && !isTampered && lastShown > 0 && now - lastShown < threeDaysMs) {
        return;
      }

      const overlay = document.createElement("div");
      overlay.style.cssText =
        "position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:99999;display:flex;align-items:center;justify-content:center;font-family:Tahoma,Segoe UI,sans-serif;user-select:none;";

      const box = document.createElement("div");
      box.style.cssText =
        "width:460px;max-width:92vw;background:#f0f0f0;border:2px solid #003366;box-shadow:0 10px 30px rgba(0,0,0,0.45);color:#111;";

      const titleText = isTampered ? cfg.titleTampered : cfg.titleNormal;
      const subText = isTampered ? cfg.subtitleTampered : cfg.subtitleNormal;

      box.innerHTML = `
        <div style="background:linear-gradient(90deg,#003366 0%,#005a9e 100%);color:#fff;padding:6px 10px;display:flex;align-items:center;justify-content:space-between;font-size:12px;font-weight:bold;">
          <span>🛡️ ${titleText}</span>
          <button id="__x509_close_x" style="background:none;border:none;color:#fff;font-size:14px;cursor:pointer;font-weight:bold;padding:0 4px;">✕</button>
        </div>
        <div style="padding:14px 16px;display:flex;flex-direction:column;gap:10px;font-size:11px;">
          <div style="background:#fff;border:1px solid #b5b5b5;padding:9px 11px;line-height:1.45;color:#222;">
            ${subText}
          </div>
          <div style="display:flex;gap:12px;align-items:center;background:#fff;border:1px solid #b5b5b5;padding:10px;">
            <div style="width:136px;height:136px;flex-shrink:0;border:1px solid #d0d0d0;padding:4px;background:#fff;display:flex;align-items:center;justify-content:center;">
              ${cfg.qrSvg}
            </div>
            <div style="display:flex;flex-direction:column;gap:6px;flex:1;min-width:0;">
              <div style="font-weight:bold;color:#003366;font-size:12px;">${cfg.authorLabel}</div>
              <div style="font-size:10px;color:#444;">Projeto Oficial: <strong style="color:#005a9e;">${cfg.repoLabel}</strong></div>
              <div style="font-size:10px;color:#333;background:#f7f9fc;border:1px solid #cbd5e1;padding:4px 6px;font-weight:600;">${cfg.receiverLabel}</div>
              <input type="text" readonly value="${cfg.pixCode}" style="width:100%;font-size:9px;font-family:monospace;padding:3px 5px;border:1px solid #999;background:#f5f5f5;color:#333;" />
              <button id="__x509_copy_btn" style="background:linear-gradient(180deg,#f0f6ff 0%,#cde2ff 100%);border:1px solid #005a9e;color:#002244;font-weight:bold;font-size:11px;padding:5px 8px;cursor:pointer;text-align:center;">
                📋 ${cfg.copyBtn}
              </button>
            </div>
          </div>
          <div style="display:flex;align-items:center;justify-content:space-between;padding-top:2px;">
            <span style="font-size:10px;color:#666;">Licença gratuita • Lembrete exibido a cada 3 dias</span>
            <button id="__x509_close_btn" style="background:linear-gradient(180deg,#ffffff 0%,#e2e2e2 100%);border:1px solid #707070;padding:4px 12px;font-size:11px;font-weight:600;cursor:pointer;color:#111;">
              ${cfg.closeBtn}
            </button>
          </div>
        </div>
      `;

      overlay.appendChild(box);
      document.body.appendChild(overlay);

      const dismiss = () => {
        localStorage.setItem(cfg.storageKey, String(Date.now()));
        overlay.remove();
      };

      box.querySelector("#__x509_close_x")?.addEventListener("click", dismiss);
      box.querySelector("#__x509_close_btn")?.addEventListener("click", dismiss);
      const copyBtn = box.querySelector("#__x509_copy_btn") as HTMLButtonElement | null;
      copyBtn?.addEventListener("click", () => {
        navigator.clipboard?.writeText(cfg.pixCode);
        if (copyBtn) {
          copyBtn.textContent = cfg.copiedBtn;
          copyBtn.style.background = "#dcfce7";
          copyBtn.style.borderColor = "#16a34a";
          copyBtn.style.color = "#14532d";
        }
      });
    } catch {
      // Ignore runtime telemetry errors
    }
  }, 2500);
}

verifyX509RuntimeChain();
